//! 🧪️ Native rendering reads the same original row and string without allocating a numerical model.
use super::*;
#[test]
fn native_model_view_borrows_original_rows_without_allocation(){let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧪️tests/🧫️fixtures/📸️snapshot/🧳️state/🔣️.json")).unwrap();let state=crate::state::tests::receive::<EnergyModelState>(&law["model"]);let row=state.geometry.zones.get(0).unwrap();let original=row as*const StateZone;let name=row.name.as_ptr();let((count,volume),heap)=crate::state::tests::observe(||{let mut count=0;let mut volume=0.0;for _ in 0..1000{let view=state.read();assert_eq!(view.zones.get(0).unwrap()as*const StateZone,original);assert_eq!(view.zones.get(0).unwrap().name.as_ptr(),name);assert_eq!(view.name.as_ptr(),state.identity.name.as_ptr());for row in view.zones.iter(){count+=1;volume+=row.volume_m3;}}(count,volume)});assert_eq!(heap,(0,0));assert_eq!(count,1000*law["model"]["zones"].as_array().unwrap().len());assert_eq!(volume,1000.0*law["model"]["zones"][0]["volume_m3"].as_f64().unwrap());crate::state::tests::drain(state);}
